package br.gov.dere.persistence;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="dere_entity_certificate") public class DereEntityCertificateEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="entity_id",nullable=false) private Long entityId; @Column(nullable=false) private String label; @Lob @Column(name="p12_ciphertext",nullable=false) private byte[] p12Ciphertext; @Column(name="password_ciphertext",nullable=false,length=1000) private String passwordCiphertext; @Column(name="alias_name") private String aliasName; @Column(name="valid_until") private Instant validUntil; private boolean active=true; @Column(name="created_at") private Instant createdAt=Instant.now(); protected DereEntityCertificateEntity(){} public DereEntityCertificateEntity(Long entityId,String label,byte[] p12,String password,String alias,Instant until){this.entityId=entityId;this.label=label;p12Ciphertext=p12;passwordCiphertext=password;aliasName=alias;validUntil=until;} public void deactivate(){active=false;} public Long getId(){return id;} public Long getEntityId(){return entityId;} public String getLabel(){return label;} public String getAliasName(){return aliasName;} public Instant getValidUntil(){return validUntil;} public boolean isActive(){return active;} public byte[] getP12Ciphertext(){return p12Ciphertext;} public String getPasswordCiphertext(){return passwordCiphertext;} }
